package com.mrpelmesok.timetrace;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity {
    private UsageTracker tracker;
    private LinearLayout root, body, nav, appsList;
    private String page="home", period="День", selectedPackage=null;
    private long selectedDate=System.currentTimeMillis();
    private boolean dark=false;
    private int bg,card,fg,muted,accent,line;
    private final SimpleDateFormat dayFmt=new SimpleDateFormat("d MMMM yyyy",new Locale("ru"));
    private final SimpleDateFormat timeFmt=new SimpleDateFormat("HH:mm",Locale.getDefault());
    private final SimpleDateFormat csvFmt=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US);
    private final int REQUEST_EXPORT=72, REQUEST_BACKUP=73, REQUEST_RESTORE=74;

    @Override public void onCreate(Bundle b){super.onCreate(b);tracker=new UsageTracker(this);dark=getPreferences(0).getBoolean("dark",false);setThemeColors();scheduleRefresh();render();}
    @Override protected void onResume(){super.onResume();if(tracker!=null&&tracker.hasAccess())new Thread(()->{tracker.sync();runOnUiThread(()->{if(body!=null)render();});}).start();}
    private void setThemeColors(){bg=Color.parseColor(dark?"#171821":"#F6F6FA");card=Color.parseColor(dark?"#242632":"#FFFFFF");fg=Color.parseColor(dark?"#F3F2FA":"#252638");muted=Color.parseColor(dark?"#A5A6B5":"#858697");int[] accents={Color.parseColor("#766BDD"),Color.parseColor("#398D83"),Color.parseColor("#D17A62")};accent=accents[getPreferences(0).getInt("accent",0)%accents.length];line=Color.parseColor(dark?"#363846":"#ECECF2");}
    private void scheduleRefresh(){Intent i=new Intent(this,RefreshReceiver.class);PendingIntent p=PendingIntent.getBroadcast(this,41,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);a.setInexactRepeating(AlarmManager.RTC,System.currentTimeMillis()+60000,15*60*1000,p);}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private TextView text(String s,int size,boolean bold,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private void pad(View v,int n){v.setPadding(n,n,n,n);}
    private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}
    private LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
    private TextView button(String label,Runnable action){TextView t=text(label,14,true,accent);t.setGravity(Gravity.CENTER);t.setPadding(dp(14),dp(11),dp(14),dp(11));t.setBackground(shape(dark?0x333766DD:0x1D766BDD,24));t.setOnClickListener(v->action.run());return t;}
    private void render(){
        setThemeColors();root=column();root.setBackgroundColor(bg);setContentView(root);
        LinearLayout header=row();header.setPadding(dp(22),dp(18),dp(22),dp(12));TextView brand=text("TimeTrace",25,true,fg);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));TextView status=text(tracker.hasAccess()?"● Отслеживание":"● Нужен доступ",12,true,tracker.hasAccess()?0xFF42A889:0xFFE39A45);header.addView(status);root.addView(header);
        body=column();body.setPadding(dp(18),dp(4),dp(18),dp(14));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(!tracker.hasAccess()) permissionCard(); else if(page.equals("home")) home(); else if(page.equals("apps")) apps(); else if(page.equals("calendar")) calendar(); else if(page.equals("settings")) settings(); else detail();
        nav=row();nav.setPadding(8,9,8,9);nav.setBackgroundColor(card);String[][] items={{"home","Обзор","⌂"},{"apps","Приложения","▦"},{"calendar","Календарь","▣"},{"settings","Настройки","⚙"}};
        for(String[] it:items){final String p=it[0];LinearLayout cell=column();cell.setGravity(Gravity.CENTER);TextView ico=text(it[2],21,true,page.equals(p)?accent:muted);TextView label=text(it[1],10,page.equals(p),page.equals(p)?accent:muted);cell.addView(ico);cell.addView(label);cell.setOnClickListener(v->{page=p;render();});nav.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);
    }
    private void permissionCard(){cardTitle("Разрешение на статистику");paragraph("Android не разрешает приложениям читать историю использования без твоего согласия. Включи доступ для TimeTrace — данные останутся на телефоне.");addGap(12);addButton("Открыть настройки доступа",()->startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS)));}
    private void cardTitle(String s){TextView t=text(s,20,true,fg);t.setPadding(0,dp(12),0,dp(8));body.addView(t);}
    private void paragraph(String s){TextView t=text(s,14,false,muted);t.setLineSpacing(4,1);body.addView(t);}
    private void addGap(int h){View v=new View(this);body.addView(v,lp(1,h));}
    private void addButton(String s,Runnable r){TextView b=button(s,r);body.addView(b,lp(-1,-2));}
    private long[] range(){Calendar c=Calendar.getInstance();c.setTimeInMillis(selectedDate);long from,to;
        if(period.equals("День")){c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);from=c.getTimeInMillis();to=from+86400000L;}
        else if(period.equals("Неделя")){c.setFirstDayOfWeek(Calendar.MONDAY);c.set(Calendar.DAY_OF_WEEK,Calendar.MONDAY);zero(c);from=c.getTimeInMillis();to=from+7L*86400000;}
        else if(period.equals("Месяц")){c.set(Calendar.DAY_OF_MONTH,1);zero(c);from=c.getTimeInMillis();c.add(Calendar.MONTH,1);to=c.getTimeInMillis();}
        else {c.set(Calendar.DAY_OF_YEAR,1);zero(c);from=c.getTimeInMillis();c.add(Calendar.YEAR,1);to=c.getTimeInMillis();}
        return new long[]{from,to};}
    private void zero(Calendar c){c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);}
    private String duration(long ms){long min=Math.max(0,ms/60000);long h=min/60,m=min%60;return h>0?h+" ч "+m+" мин":m+" мин";}
    private void periodPicker(){LinearLayout r=row();for(String p:new String[]{"День","Неделя","Месяц","Год"}){TextView b=text(p,12,true,period.equals(p)?Color.WHITE:muted);b.setGravity(Gravity.CENTER);b.setPadding(7,10,7,10);b.setBackground(shape(period.equals(p)?accent:bg,18));b.setOnClickListener(v->{period=p;render();});r.addView(b,new LinearLayout.LayoutParams(0,-2,1));}body.addView(r);}
    private void datePicker(){LinearLayout r=row();TextView prev=button("‹",()->{Calendar c=Calendar.getInstance();c.setTimeInMillis(selectedDate);c.add(period.equals("Год")?Calendar.YEAR:period.equals("Месяц")?Calendar.MONTH:period.equals("Неделя")?Calendar.WEEK_OF_YEAR:Calendar.DAY_OF_YEAR,-1);selectedDate=c.getTimeInMillis();render();});TextView date=text(dayFmt.format(new Date(selectedDate)),14,true,fg);date.setGravity(Gravity.CENTER);date.setOnClickListener(v->new DatePickerDialog(this,(view,y,m,d)->{Calendar c=Calendar.getInstance();c.set(y,m,d);selectedDate=c.getTimeInMillis();render();},Calendar.getInstance().get(Calendar.YEAR),Calendar.getInstance().get(Calendar.MONTH),Calendar.getInstance().get(Calendar.DAY_OF_MONTH)).show());TextView next=button("›",()->{Calendar c=Calendar.getInstance();c.setTimeInMillis(selectedDate);c.add(period.equals("Год")?Calendar.YEAR:period.equals("Месяц")?Calendar.MONTH:period.equals("Неделя")?Calendar.WEEK_OF_YEAR:Calendar.DAY_OF_YEAR,1);selectedDate=c.getTimeInMillis();render();});r.addView(prev);r.addView(date,new LinearLayout.LayoutParams(0,-2,1));r.addView(next);body.addView(r);}
    private LinearLayout panel(){LinearLayout p=column();p.setPadding(16,15,16,15);p.setBackground(shape(card,22));LinearLayout.LayoutParams x=lp(-1,-2);x.topMargin=12;body.addView(p,x);return p;}
    private void home(){cardTitle("Твоя активность");periodPicker();addGap(10);datePicker();long[] rg=range();Map<String,Long> sums=tracker.aggregate(rg[0],rg[1]);long total=0;for(long v:sums.values())total+=v;
        LinearLayout p=panel();p.addView(text("ОБЩЕЕ ВРЕМЯ",11,true,muted));p.addView(text(duration(total),34,true,fg));p.addView(text(sums.size()+" приложений · "+tracker.sessions(null,rg[0],rg[1]).size()+" сеансов",13,false,muted));
        LinearLayout p2=panel();p2.addView(text("Чаще всего",17,true,fg));ArrayList<Map.Entry<String,Long>> entries=new ArrayList<>(sums.entrySet());entries.sort((a,b)->Long.compare(b.getValue(),a.getValue()));if(entries.isEmpty())p2.addView(text("Пока нет сохранённых сеансов за этот период",13,false,muted));for(int i=0;i<Math.min(5,entries.size());i++)appRow(p2,entries.get(i).getKey(),entries.get(i).getValue(),rg[0],rg[1]);
        LinearLayout p3=panel();p3.addView(text("Активность по приложениям",17,true,fg));if(!entries.isEmpty()){long max=entries.get(0).getValue();for(int i=0;i<Math.min(6,entries.size());i++){Map.Entry<String,Long> e=entries.get(i);TextView name=text(tracker.label(e.getKey())+" · "+duration(e.getValue()),12,false,fg);p3.addView(name);View bar=new View(this);bar.setBackground(shape(accent,8));LinearLayout.LayoutParams bp=lp(-1,7);bp.topMargin=5;bp.bottomMargin=10;bar.setLayoutParams(bp);bar.setMinimumWidth(dp((int)(Math.max(20,260.0*e.getValue()/Math.max(1,max)))));p3.addView(bar);}}}
    private void appRow(LinearLayout parent,String pkg,long ms,long from,long to){LinearLayout r=row();android.graphics.drawable.Drawable icon=tracker.icon(pkg);if(icon!=null){ImageView iv=new ImageView(this);iv.setImageDrawable(icon);r.addView(iv,lp(38,38));}LinearLayout info=column();info.setPadding(10,0,0,0);info.addView(text(tracker.label(pkg),14,true,fg));info.addView(text(pkg,10,false,muted));r.addView(info,new LinearLayout.LayoutParams(0,-2,1));r.addView(text(duration(ms),13,true,fg));r.setPadding(0,dp(10),0,dp(10));r.setOnClickListener(v->{selectedPackage=pkg;page="detail";render();});parent.addView(r);View d=new View(this);d.setBackgroundColor(line);parent.addView(d,lp(-1,1));}
    private void apps(){cardTitle("Приложения");EditText search=new EditText(this);search.setSingleLine(true);search.setTextSize(14);search.setHint("Поиск приложения");search.setTextColor(fg);search.setHintTextColor(muted);search.setBackground(shape(card,18));search.setPadding(dp(14),dp(10),dp(14),dp(10));body.addView(search,lp(-1,-2));periodPicker();addGap(10);datePicker();appsList=column();body.addView(appsList);updateAppList("");search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){} public void onTextChanged(CharSequence s,int st,int before,int count){updateAppList(s.toString());} public void afterTextChanged(android.text.Editable e){}});}
    private void updateAppList(String query){if(appsList==null)return;appsList.removeAllViews();long[] rg=range();Map<String,Long> sums=tracker.aggregate(rg[0],rg[1]);ArrayList<Map.Entry<String,Long>> e=new ArrayList<>(sums.entrySet());e.sort((a,b)->Long.compare(b.getValue(),a.getValue()));String q=query.toLowerCase(new Locale("ru"));for(Map.Entry<String,Long> x:e){if(!tracker.label(x.getKey()).toLowerCase(new Locale("ru")).contains(q) && !x.getKey().toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout p=column();p.setPadding(dp(15),dp(7),dp(15),dp(7));p.setBackground(shape(card,20));LinearLayout.LayoutParams pp=lp(-1,-2);pp.topMargin=9;appsList.addView(p,pp);appRow(p,x.getKey(),x.getValue(),rg[0],rg[1]);}if(appsList.getChildCount()==0){TextView empty=text("Нет приложений с активностью за этот период",13,false,muted);empty.setPadding(dp(4),dp(20),dp(4),dp(20));appsList.addView(empty);}}
    private void calendar(){cardTitle("Календарь");paragraph("Выбери дату, чтобы посмотреть сохранённую активность.");addGap(10);datePicker();long[] rg=range();Map<String,Long> sums=tracker.aggregate(rg[0],rg[1]);LinearLayout p=panel();p.addView(text("Итого за выбранный период",15,true,fg));long total=0;for(long v:sums.values())total+=v;p.addView(text(duration(total),30,true,accent));p.addView(text(sums.size()+" приложений",13,false,muted));addGap(10);addButton("Выбрать другую дату",()->new DatePickerDialog(this,(v,y,m,d)->{Calendar c=Calendar.getInstance();c.set(y,m,d);selectedDate=c.getTimeInMillis();period="День";render();},Calendar.getInstance().get(Calendar.YEAR),Calendar.getInstance().get(Calendar.MONTH),Calendar.getInstance().get(Calendar.DAY_OF_MONTH)).show());}
    private void detail(){String pkg=selectedPackage;if(pkg==null){page="apps";render();return;}cardTitle(tracker.label(pkg));TextView back=button("← Все приложения",()->{page="apps";render();});body.addView(back);long[] rg=range();long total=tracker.aggregate(rg[0],rg[1]).getOrDefault(pkg,0L);LinearLayout p=panel();p.addView(text("Время использования",12,true,muted));p.addView(text(duration(total),30,true,fg));p.addView(text(pkg,11,false,muted));LinearLayout history=panel();history.addView(text("Сеансы",17,true,fg));List<SessionStore.Session> sessions=tracker.sessions(pkg,rg[0],rg[1]);if(sessions.isEmpty())history.addView(text("Сеансов за этот период пока нет",13,false,muted));for(SessionStore.Session s:sessions){TextView t=text(new Date(s.start).toString()+"\n"+timeFmt.format(new Date(s.start))+" — "+timeFmt.format(new Date(s.end))+" · "+duration(s.duration),13,false,fg);t.setPadding(0,dp(10),0,dp(10));history.addView(t);View d=new View(this);d.setBackgroundColor(line);history.addView(d,lp(-1,1));}}
    private void settings(){cardTitle("Настройки");LinearLayout p=panel();p.addView(text("Внешний вид",17,true,fg));Switch sw=new Switch(this);sw.setText("Тёмная тема");sw.setTextColor(fg);sw.setChecked(dark);sw.setOnCheckedChangeListener((b,v)->{dark=v;getPreferences(0).edit().putBoolean("dark",v).apply();render();});p.addView(sw);p.addView(text("Цвет акцента",13,true,muted));LinearLayout colors=row();String[] names={"Лавандовый","Мятный","Терракотовый"};for(int i=0;i<3;i++){final int ix=i;TextView c=button(names[i],()->{getPreferences(0).edit().putInt("accent",ix).apply();render();});LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(dp(3),dp(8),dp(3),dp(4));colors.addView(c,cp);}p.addView(colors);LinearLayout p2=panel();p2.addView(text("Отслеживание",17,true,fg));p2.addView(text("Проверка истории примерно каждые 15 минут и при открытии приложения. Автозапуск после перезагрузки включён через системный приёмник. Android и MIUI могут задерживать фоновые проверки в режиме энергосбережения.",13,false,muted));addGap(10);addButton("Проверить доступ Usage Access",()->startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS)));LinearLayout p3=panel();p3.addView(text("Уведомления",17,true,fg));Switch reminder=new Switch(this);reminder.setText("Ежедневное напоминание вечером");reminder.setTextColor(fg);reminder.setChecked(getPreferences(0).getBoolean("reminder",false));reminder.setOnCheckedChangeListener((b,v)->{getPreferences(0).edit().putBoolean("reminder",v).apply();if(v){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},91);scheduleReminder();}else cancelReminder();});p3.addView(reminder);LinearLayout p4=panel();p4.addView(text("Резервная копия и экспорт",17,true,fg));addButton("Создать резервную копию (JSON)",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"TimeTrace-backup.json");startActivityForResult(i,REQUEST_BACKUP);});addGap(8);addButton("Восстановить из JSON",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");startActivityForResult(i,REQUEST_RESTORE);});addGap(8);addButton("Экспортировать историю в CSV",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"TimeTrace-history.csv");startActivityForResult(i,REQUEST_EXPORT);});addGap(8);addButton("Сбросить локальную историю",()->new AlertDialog.Builder(this).setTitle("Удалить историю?").setMessage("Все сохранённые сеансы TimeTrace будут удалены. Это действие нельзя отменить.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->{new SessionStore(this).clear();render();}).show());}
    private void renderAppsOnly(String q){if(!page.equals("apps"))return;render();}
    private void scheduleReminder(){if(!getPreferences(0).getBoolean("reminder",false))return;Intent i=new Intent(this,ReminderReceiver.class);PendingIntent pi=PendingIntent.getBroadcast(this,99,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,20);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);if(c.getTimeInMillis()<System.currentTimeMillis())c.add(Calendar.DAY_OF_YEAR,1);((AlarmManager)getSystemService(ALARM_SERVICE)).setInexactRepeating(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),AlarmManager.INTERVAL_DAY,pi);}
    private void cancelReminder(){Intent i=new Intent(this,ReminderReceiver.class);PendingIntent pi=PendingIntent.getBroadcast(this,99,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(pi);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;if(request==REQUEST_EXPORT)exportCsv(data.getData());else if(request==REQUEST_BACKUP)backupJson(data.getData());else if(request==REQUEST_RESTORE)restoreJson(data.getData());}
    private void backupJson(Uri uri){try(java.io.OutputStream out=getContentResolver().openOutputStream(uri);java.io.OutputStreamWriter w=new java.io.OutputStreamWriter(out,"UTF-8")){org.json.JSONArray a=new org.json.JSONArray();for(SessionStore.Session s:tracker.sessions(null,0,System.currentTimeMillis())){org.json.JSONObject o=new org.json.JSONObject();o.put("package",s.pkg);o.put("start",s.start);o.put("end",s.end);o.put("duration",s.duration);a.put(o);}org.json.JSONObject root=new org.json.JSONObject();root.put("format","TimeTraceBackup");root.put("version",1);root.put("sessions",a);w.write(root.toString());Toast.makeText(this,"Резервная копия создана",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Ошибка создания копии",Toast.LENGTH_LONG).show();}}
    private void restoreJson(Uri uri){try(java.io.InputStream in=getContentResolver().openInputStream(uri)){java.io.ByteArrayOutputStream buffer=new java.io.ByteArrayOutputStream();byte[] chunk=new byte[8192];int n;while((n=in.read(chunk))!=-1)buffer.write(chunk,0,n);org.json.JSONObject root=new org.json.JSONObject(buffer.toString("UTF-8"));if(!"TimeTraceBackup".equals(root.optString("format")))throw new Exception("wrong format");org.json.JSONArray a=root.getJSONArray("sessions");SessionStore db=new SessionStore(this);for(int i=0;i<a.length();i++){org.json.JSONObject o=a.getJSONObject(i);db.put(o.getString("package"),o.getLong("start"),o.getLong("end"));}Toast.makeText(this,"Восстановлено сеансов: "+a.length(),Toast.LENGTH_LONG).show();render();}catch(Exception e){Toast.makeText(this,"Не удалось прочитать резервную копию",Toast.LENGTH_LONG).show();}}
    private void exportCsv(Uri uri){try(java.io.OutputStream out=getContentResolver().openOutputStream(uri);java.io.OutputStreamWriter w=new java.io.OutputStreamWriter(out,"UTF-8")){w.write("package,app,start,end,duration_ms\n");long from=0,to=System.currentTimeMillis();for(SessionStore.Session s:tracker.sessions(null,from,to)){String label=tracker.label(s.pkg).replace("\"","\"\"");w.write("\""+s.pkg+"\",\""+label+"\",\""+csvFmt.format(new Date(s.start))+"\",\""+csvFmt.format(new Date(s.end))+"\","+s.duration+"\n");}Toast.makeText(this,"Экспорт завершён",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Не удалось сохранить CSV",Toast.LENGTH_LONG).show();}}
}
